class Employee:
    def __init__(self, name, employee_id, salary):
        self.name = name
        self.employee_id = employee_id
        self.salary = salary

    def raise_salary(self, percent):
        self.salary = self.salary * (1 + percent / 100)

    def to_string(self):
        return 'Employee: ' + self.name + ', ID: ' + self.employee_id + ', Salary: $' + str(self.salary)

emp = Employee('Bob Jones', 'E102', 60000)
emp.raise_salary(10)
print(emp.to_string())

