class Vehicle:
    def __init__(self, make, model, year):
        self.make = make
        self.model = model
        self.year = year

    def describe(self):
        print('Vehicle: ' + self.make + ' ' + self.model + ' (' + str(self.year) + ')')

class ElectricCar(Vehicle):
    def __init__(self, make, model, year, battery_size):
        super().__init__(make, model, year)
        self.battery_size = battery_size

    def describe(self):
        print('Electric Car: ' + self.make + ' ' + self.model + ' (' + str(self.year) + '), Battery: ' + str(self.battery_size) + ' kWh')

car = ElectricCar('Tesla', 'Model S', 2023, 75)
car.describe()

